# 1992_Q1.sav -- Pollara, 10 demographic variables
survey(
  survey_id = "1992_Q1.sav",
  source    = "Pollara",
  file_name = "1992_Q1.sav",
  demographics = function(..d) {
    ..d %>% transmute(
      # age_cats <- q1 | AGE (IN YRS): GROUPED
      age_cats = recode_values(as.numeric(..d[["q1"]]), 1 ~ 1, 3 ~ 2, 5 ~ 3, 6 ~ 3),
      # degree <- q88 | EDUCATION
      degree = recode_values(as.numeric(..d[["q88"]]), 1:4 ~ 0, 5 ~ 1),
      # gender <- q94 | SEX
      gender = recode_values(as.numeric(..d[["q94"]]), 1 ~ 0, 2 ~ 1),
      # occupation <- q91a or q91 | OCCUPATION-RECODE
      occupation = coalesce(recode_values(as.numeric(..d[["q91a"]]), 1 ~ 3, 2 ~ 2, 3 ~ 4, 4 ~ 99, 7 ~ 9, 8 ~ 7, 9 ~ 8), recode_values(as.numeric(..d[["q91"]]), 5 ~ 6, 6 ~ 5)),
      # province <- q93a | PROVINCE
      province = recode_values(as.numeric(..d[["q93a"]]), 1 ~ 59, 2 ~ 48, 3 ~ 47, 4 ~ 46, 5 ~ 35, 6 ~ 10, 7 ~ 11, 8 ~ 12, 9 ~ 13, 10 ~ 24),
      # region <- q93b | REGION-5 GROUPS
      region = recode_values(as.numeric(..d[["q93b"]]), 1 ~ 5, 2 ~ 4, 3 ~ 3, 4 ~ 1, 5 ~ 2),
      # survey_mode <- assigned by hand | assigned by hand; not in the survey file
      survey_mode = rep(3, nrow(..d)),
      # union_household <- q90 | LABOUR UNION
      union_household = recode_values(as.numeric(..d[["q90"]]), 1 ~ 1, 2 ~ 0),
      # vote_choice <- q16 | 1988 FEDERAL ELECTION VOTE
      vote_choice = recode_values(as.numeric(..d[["q16"]]), 1 ~ 1, 2 ~ 2, 3 ~ 3, 4 ~ 8, 5 ~ 9, 6 ~ 96, 7 ~ 99),
      # vote_intention <- q17 | CURRENT FEDERAL VOTE - SOLID
      vote_intention = recode_values(as.numeric(..d[["q17"]]), 1 ~ 1, 2 ~ 2, 3 ~ 3, 4 ~ 8, 5 ~ 6, 6 ~ 9, 7 ~ 99, 8 ~ 96, 9 ~ 98)
    )
  }
)

