      vote_intention = coalesce(recode_values(as.numeric(..d[["q7b"]]), 1 ~ 1, 2 ~ 2, 3 ~ 3, 4 ~ 8, 5 ~ 6, 6 ~ 9, 7 ~ 99), recode_values(as.numeric(..d[["q7a"]]), 8 ~ 96, 7 ~ 99, 9 ~ 98))
    )
  }
)

# 2002_Q4.sav -- Pollara, 9 demographic variables
survey(
  survey_id = "2002_Q4.sav",
  source    = "Pollara",
  file_name = "2002_Q4.sav",
  demographics = function(..d) {
    ..d %>% transmute(
      # age <- q1a | AGE 2 (IN YRS)
      age = in_range(..d[["q1a"]], 19, 97),
      # age_cats <- age | constructed from continuous age
      age_cats = recode_values(as.numeric(age), 0:29 ~ 1, 30:49 ~ 2, 50:125 ~ 3),
      # degree <- q96 | EDUCATION
      degree = recode_values(as.numeric(..d[["q96"]]), 1:4 ~ 0, 5:6 ~ 1),
      # gender <- q108 | GENDER
      gender = recode_values(as.numeric(..d[["q108"]]), 1 ~ 0, 2 ~ 1),
      # province <- q112 | PROVINCE
      province = recode_values(as.numeric(..d[["q112"]]), 1 ~ 10, 2 ~ 12, 3 ~ 13, 4 ~ 11, 5 ~ 24, 6 ~ 35, 7 ~ 46, 8 ~ 47, 9 ~ 48, 10 ~ 59, 11 ~ 60, 12 ~ 61, 13 ~ 62),
      # region <- rr | SUB REGION
      region = recode_values(as.numeric(..d[["rr"]]), 1:4 ~ 1, 13:17 ~ 4, 18:22 ~ 5, 23:25 ~ 6, 31:35 ~ 2, 40:48 ~ 3),
      # survey_mode <- assigned by hand | assigned by hand; not in the survey file
      survey_mode = rep(3, nrow(..d)),
      # vote_choice <- q5 | PARTY VOTED FOR IN LAST FED ELECTION
      vote_choice = recode_values(as.numeric(..d[["q5"]]), 1 ~ 1, 2 ~ 2, 3 ~ 3, 4 ~ 8, 5 ~ 6, 6 ~ 9, 8 ~ 99, 10 ~ 96, 7 ~ 99, 9 ~ 98),
      # vote_intention <- q7b or q7a | FED VOTE INTENT POTENTIAL
      vote_intention = coalesce(recode_values(as.numeric(..d[["q7b"]]), 1 ~ 1, 2 ~ 2, 3 ~ 3, 4 ~ 8, 5 ~ 6, 6 ~ 9, 7 ~ 99), recode_values(as.numeric(..d[["q7a"]]), 8 ~ 96, 7 ~ 99, 9 ~ 98))
    )
  }
)
